int main() {
    int n, x;

    scanf("%d", &n);

    int arr[n];
    for (int i = 0; i < n; i++) {
        scanf("%d", &arr[i]);
    }

    scanf("%d", &x);

    int l = 0, r = n - 1;
    int res = -1;

    while (l <= r) {
        int mid = (l + r) / 2;

        if (arr[mid] == x) {
            res = mid;
            break;
        }

        if (arr[l] <= arr[mid]) {  
            // Left half is sorted
            if (arr[l] <= x && x < arr[mid]) {
                r = mid - 1;
            } else {
                l = mid + 1;
            }
        } 
        else {  
            // Right half is sorted
            if (arr[mid] < x && x <= arr[r]) {
                l = mid + 1;
            } else {
                r = mid - 1;
            }
        }
    }

    printf("%d", res);

    return 0;
}

