#include <stdlib.h>
#include <limits.h>

int cmp(const void* a, const void* b) {
    long long x = *(long long*)a;
    long long y = *(long long*)b;
    return (x > y) - (x < y);
}

int main() {
    int n;
    scanf("%d", &n);

    long long a[n], p[n + 1];
    p[0] = 0;

    for (int i = 0; i < n; i++) {
        scanf("%lld", &a[i]);
        p[i + 1] = p[i] + a[i];
    }

    qsort(p, n + 1, sizeof(long long), cmp);

    long long best = LLONG_MAX;


    for (int i = 1; i <= n; i++) {
        long long d = llabs(p[i] - p[i - 1]);
        if (d < best) best = d;
    }

    printf("%lld", best);

    return 0;
}

