  for(char c:t.toCharArray()) need.put(c,need.getOrDefault(c,0)+1);
  Map<Character,Integer> window=new HashMap<>();
  int have=0,req=need.size(),l=0,start=0,len=Integer.MAX_VALUE;
  for(int r=0;r<s.length();r++){
   char c=s.charAt(r);
   window.put(c,window.getOrDefault(c,0)+1);
   if(need.containsKey(c) && window.get(c).intValue()==need.get(c).intValue()) have++;
   while(have==req){
    if(r-l+1<len){len=r-l+1;start=l;}
    char ch=s.charAt(l);
    window.put(ch,window.get(ch)-1);
    if(need.containsKey(ch) && window.get(ch)<need.get(ch)) have--;
    l++;
   }
  }
  System.out.print(len==Integer.MAX_VALUE?"":s.substring(start,start+len));
 }
}

