    int required = 0;

    for (int i = 0; t[i]; i++) {
        if (need[t[i]] == 0)
            required++;
        need[t[i]]++;
    }

    int formed = 0, l = 0, start = 0, minLen = INT_MAX;

    for (int r = 0; s[r]; r++) {
        window[s[r]]++;
        if (need[s[r]] && window[s[r]] == need[s[r]])
            formed++;

        while (formed == required) {
            if (r - l + 1 < minLen) {
                minLen = r - l + 1;
                start = l;
            }

            window[s[l]]--;
            if (need[s[l]] && window[s[l]] < need[s[l]])
                formed--;
            l++;
        }
    }

    if (minLen == INT_MAX)
        printf("");
    else {
        for (int i = start; i < start + minLen; i++)
            printf("%c", s[i]);
    }

    return 0;
}

