#include <string.h>

void expand(char *s, int l, int r, int *start, int *maxLen) {
    int n = strlen(s);

    while (l >= 0 && r < n && s[l] == s[r]) {
        if (r - l + 1 > *maxLen) {
            *start = l;
            *maxLen = r - l + 1;
        }
        l--;
        r++;
    }
}

