 int left=0,res=0;
 for(int right=0;right<s.length();right++){
  mp[s[right]]++;
  while(mp.size()>k){
   mp[s[left]]--;
   if(mp[s[left]]==0) mp.erase(s[left]);
   left++;
  }
  res+=right-left+1;
 }
 return res;
}
