int atMost(char *s, int k) {
    int freq[256] = {0}, left = 0, res = 0, distinct = 0;

    for (int right = 0; s[right]; right++) {
        if (freq[(unsigned char)s[right]]++ == 0)
            distinct++;

        while (distinct > k) {
            if (--freq[(unsigned char)s[left]] == 0)
                distinct--;
            left++;
        }

        res += right - left + 1;
    }

    return res;
}

