    int n = strlen(s), res = 0;
    int dp[n][n];

    for (int g = 0; g < n; g++) {
        for (int i = 0; i + g < n; i++) {
            int j = i + g;

            if (g == 0)
                dp[i][j] = 1;
            else if (g == 1)
                dp[i][j] = (s[i] == s[j]);
            else
                dp[i][j] = (s[i] == s[j] && dp[i + 1][j - 1]);

            if (dp[i][j])
                res++;
        }
    }

    printf("%d", res);
    return 0;
}

