class FreqStack {
public:
    unordered_map<int,int> freq;
    unordered_map<int, vector<int>> group;
    int maxf = 0;

    void push(int x){
        int f = ++freq[x];
        maxf = max(maxf, f);
        group[f].push_back(x);
    }

    int pop(){
        int x = group[maxf].back();
        group[maxf].pop_back();
        freq[x]--;

        if(group[maxf].empty())
            maxf--;

        return x;
    }
};

