void push(int x) {

    int f = ++freq[x];

    if (f > maxf) {
        maxf = f;
    }

    group[f][top[f]++] = x;
}

int pop() {

    int x = group[maxf][--top[maxf]];

    freq[x]--;

    if (top[maxf] == 0) {
        maxf--;
    }

    return x;
}

