        while(i<n){
            if(code.startsWith("<![CDATA[",i)){
                int j=code.indexOf("]]>",i);
                if(j==-1){System.out.print("false");return;}
                i=j+3;
            }
            else if(code.startsWith("</",i)){
                int j=code.indexOf('>',i);
                if(j==-1){System.out.print("false");return;}
                String tag=code.substring(i+2,j);
                if(stack.isEmpty() || !stack.pop().equals(tag)){
                    System.out.print("false");return;
                }
                i=j+1;
            }
            else if(code.startsWith("<",i)){
                int j=code.indexOf('>',i);
                if(j==-1){System.out.print("false");return;}
                String tag=code.substring(i+1,j);
                if(!tag.matches("[A-Z]{1,9}")){
                    System.out.print("false");return;
                }
                stack.push(tag);
                i=j+1;
            }
            else i++;
        }
        System.out.print(stack.isEmpty()?"true":"false");
    }
}

