  int maxArea=0;
  for(int i=0;i<=n;i++){
   int h=(i==n)?0:arr.get(i);
   while(!stack.isEmpty() && arr.get(stack.peek())>h){
    int height=arr.get(stack.pop());
    int width=stack.isEmpty()?i:i-stack.peek()-1;
    maxArea=Math.max(maxArea,height*width);
   }
   stack.push(i);
  }
  System.out.print(maxArea);
 }
