public class Solution{
 public static void main(String[] args){
  Scanner sc=new Scanner(System.in);
  String s=sc.nextLine();
  ArrayList<Integer> arr=new ArrayList<>();
  String num="";
  for(char c:s.toCharArray()){
   if(Character.isDigit(c)||c=='-') num+=c;
   else if(!num.isEmpty()){ arr.add(Integer.parseInt(num)); num=""; }
  }
  if(!num.isEmpty()) arr.add(Integer.parseInt(num));
  int n=arr.size();
  long res=0; int mod=1000000007;
  Stack<Integer> stack=new Stack<>();
  for(int i=0;i<=n;i++){
   while(!stack.isEmpty() && (i==n || arr.get(stack.peek())>arr.get(i))){
    int mid=stack.pop();
    int left=mid-(stack.isEmpty()?-1:stack.peek());
    int right=i-mid;
    res+=(long)arr.get(mid)*left*right;
   }
   stack.push(i);
  }
  System.out.print(res%mod);
 }
}

