import java.util.*;
import java.util.regex.*;

class Solution {

    static Queue<Integer> q = new LinkedList<>();
    static Map<Integer,Integer> freq = new HashMap<>();

    static void add(int v){
        freq.put(v,freq.getOrDefault(v,0)+1);
        q.add(v);
    }

    static int showFirstUnique(){
        while(!q.isEmpty() && freq.get(q.peek())>1)
            q.poll();
        return q.isEmpty()? -1:q.peek();
    }

    public static void main(String[] args){

        Scanner sc = new Scanner(System.in);
        String line = sc.nextLine();

        Pattern p = Pattern.compile("nums=\\[(.*?)\\]");
        Matcher m = p.matcher(line);

        if(m.find()){
            String arr = m.group(1);
            if(!arr.isEmpty()){
                for(String s : arr.split(",")){
                    add(Integer.parseInt(s.trim()));
                }
            }
        }

        line = line.replaceAll("nums=\\[.*?\\],?\\s*", "");

        String[] ops = line.split(",");

        List<String> res = new ArrayList<>();

        for(String op : ops){

            op = op.trim();

            if(op.startsWith("add")){
                int v = Integer.parseInt(op.substring(4,op.length()-1));
                add(v);
            }

            else if(op.startsWith("showFirstUnique")){
                res.add(String.valueOf(showFirstUnique()));
            }
        }

        System.out.println(String.join(",",res));
    }
}

