class MKAverage{

    int m,k;
    Queue<Integer> q=new LinkedList<>();

    MKAverage(int m,int k){
        this.m=m;
        this.k=k;
    }

    void addElement(int num){
        q.add(num);
        if(q.size()>m) q.poll();
    }

    int calculateMKAverage(){

        if(q.size()<m) return -1;

        List<Integer> list=new ArrayList<>(q);
        Collections.sort(list);

        int sum=0;

        for(int i=k;i<m-k;i++)
            sum+=list.get(i);

        return sum/(m-2*k);
    }
}

