import java.util.*;

public class Solution {

    static final int INF = 2147483647;

    static void wallsAndGates(int[][] rooms){
        int m=rooms.length;
        int n=rooms[0].length;

        Queue<int[]> q=new LinkedList<>();

        for(int i=0;i<m;i++)
            for(int j=0;j<n;j++)
                if(rooms[i][j]==0)
                    q.offer(new int[]{i,j});

        int[][] dirs={{1,0},{-1,0},{0,1},{0,-1}};

        while(!q.isEmpty()){
            int[] cur=q.poll();
            int r=cur[0],c=cur[1];

            for(int[] d:dirs){
                int nr=r+d[0];
                int nc=c+d[1];

                if(nr>=0 && nr<m && nc>=0 && nc<n && rooms[nr][nc]==INF){
                    rooms[nr][nc]=rooms[r][c]+1;
                    q.offer(new int[]{nr,nc});
                }
            }
        }
    }

    public static void main(String[] args){
        Scanner sc=new Scanner(System.in);
        String line=sc.nextLine().trim();

        String grid=line.split("=",2)[1]
                .replace("INF",String.valueOf(INF));

        grid=grid.substring(2,grid.length()-2);
        String[] rows=grid.split("\\],\\[");

        int m=rows.length;
        int n=rows[0].split(",").length;

        int[][] rooms=new int[m][n];

        for(int i=0;i<m;i++){
            String[] vals=rows[i].split(",");
            for(int j=0;j<n;j++)
                rooms[i][j]=Integer.parseInt(vals[j]);
        }

        wallsAndGates(rooms);

        StringBuilder sb=new StringBuilder();
        sb.append("[");

        for(int i=0;i<m;i++){
            sb.append("[");
            for(int j=0;j<n;j++){
                if(rooms[i][j]==INF) sb.append("INF");
                else sb.append(rooms[i][j]);

                if(j<n-1) sb.append(",");
            }
            sb.append("]");
            if(i<m-1) sb.append(",");
        }

        sb.append("]");
        System.out.println(sb.toString());
    }
}

