    vector<int> nums;
    stringstream ss(arr);
    string temp;

    while(getline(ss,temp,','))
        nums.push_back(stoi(temp));

    int k = stoi(line.substr(line.find("k=")+2));

    int n = nums.size();

    vector<long long> prefix(n+1,0);

    for(int i=0;i<n;i++)
        prefix[i+1] = prefix[i] + nums[i];

    deque<int> dq;

    int res = n+1;

    for(int i=0;i<=n;i++){

        while(!dq.empty() && prefix[i] - prefix[dq.front()] >= k){
            res = min(res, i - dq.front());
            dq.pop_front();
        }

        while(!dq.empty() && prefix[i] <= prefix[dq.back()])
            dq.pop_back();

        dq.push_back(i);
    }

    cout<<(res<=n ? res : -1);
}

