int totalSteps(int nums[], int n) {
    int stack_val[n], stack_step[n];
    int top = -1;
    int result = 0;

    for (int i = 0; i < n; i++) {
        int step = 0;

        while (top >= 0 && nums[i] >= stack_val[top]) {
            if (stack_step[top] > step)
                step = stack_step[top];
            top--;
        }

        if (top >= 0)
            step++;
        else
            step = 0;

        if (step > result)
            result = step;

        stack_val[++top] = nums[i];
        stack_step[top] = step;
    }

    return result;
}

