        for (int j = 0; j < n; j++) {
            if (j == i || j == i + 1) continue;
            next[idx++] = arr[j];
        }

        int ops = 1 + solve(next, n - 2);
        if (ops < best) {
            best = ops;
        }

        free(next);
    }

    return best;
}

