vector<vector<int>> extractBracketArrays(const string& s) {
    vector<vector<int>> arrays;
    int n = (int)s.size();

    for (int i = 0; i < n; i++) {
        if (s[i] != '[') continue;

        int j = i + 1;
        int depth = 1;

        while (j < n && depth > 0) {
            if (s[j] == '[') depth++;
            else if (s[j] == ']') depth--;
            j++;
        }

        if (depth == 0) {
            string part = s.substr(i, j - i);

            bool hasDigit = false;
            for (char c : part) {
                if (isdigit((unsigned char)c)) {
                    hasDigit = true;
                    break;
                }
            }

            if (hasDigit) {
                arrays.push_back(parseOneArray(part));
            }

            i = j - 1;
        }
    }

    return arrays;
}

