import java.util.*;
import java.util.regex.*;

class ListNode {
    int val;
    ListNode next;

    ListNode(int val) {
        this.val = val;
        this.next = null;
    }
}

public class Solution {

    public ListNode getIntersectionNode(ListNode headA, ListNode headB) {
        ListNode a = headA;
        ListNode b = headB;

        while (a != b) {
            a = (a == null) ? headB : a.next;
            b = (b == null) ? headA : b.next;
        }

        return a;
    }

    static ListNode buildList(List<Integer> arr) {
        if (arr.isEmpty()) return null;

        ListNode head = new ListNode(arr.get(0));
        ListNode tail = head;

        for (int i = 1; i < arr.size(); i++) {
            tail.next = new ListNode(arr.get(i));
            tail = tail.next;
        }

        return head;
    }

    static ListNode getTail(ListNode head) {
        if (head == null) return null;
        while (head.next != null) head = head.next;
        return head;
    }

    static List<Integer> extractNumbers(String s) {
        List<Integer> nums = new ArrayList<>();
        Matcher m = Pattern.compile("-?\\d+").matcher(s);

        while (m.find()) {
            nums.add(Integer.parseInt(m.group()));
        }

        return nums;
    }

    static List<Integer> extractList(String input, String key) {
        int start = input.indexOf(key);
        if (start == -1) return new ArrayList<>();

        int lb = input.indexOf('[', start);
        int rb = input.indexOf(']', lb);
        if (lb == -1 || rb == -1) return new ArrayList<>();

        String part = input.substring(lb, rb + 1);
        return extractNumbers(part);
    }

    static int extractValue(String input, String key) {
        int start = input.indexOf(key);
        if (start == -1) return 0;

        int eq = input.indexOf('=', start);
        if (eq == -1) return 0;

        String part = input.substring(eq + 1);
        List<Integer> nums = extractNumbers(part);
        return nums.isEmpty() ? 0 : nums.get(0);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        StringBuilder inputBuilder = new StringBuilder();

        while (sc.hasNextLine()) {
            inputBuilder.append(sc.nextLine()).append(" ");
        }

        String input = inputBuilder.toString();

        List<Integer> listA = extractList(input, "listA");
        List<Integer> listB = extractList(input, "listB");

        int intersectVal = extractValue(input, "intersectVal");
        int skipA = extractValue(input, "skipA");
        int skipB = extractValue(input, "skipB");

        ListNode headA;
        ListNode headB;

        if (intersectVal == 0) {
            headA = buildList(listA);
            headB = buildList(listB);
        } else {
            List<Integer> common = new ArrayList<>();
            for (int i = skipA; i < listA.size(); i++) {
                common.add(listA.get(i));
            }

            ListNode commonHead = buildList(common);

            headA = buildList(listA.subList(0, skipA));
            headB = buildList(listB.subList(0, skipB));

            if (headA != null) {
                getTail(headA).next = commonHead;
            } else {
                headA = commonHead;
            }

            if (headB != null) {
                getTail(headB).next = commonHead;
            } else {
                headB = commonHead;
            }
        }

        Solution sol = new Solution();
        ListNode ans = sol.getIntersectionNode(headA, headB);

        if (ans != null) {
            System.out.print("Node with value " + ans.val);
        } else {
            System.out.print("null");
        }
    }
}

