            inside = s[i + 1:j]
            if ',' in inside:
                a, b = inside.split(',', 1)
                a = a.strip()
                b = b.strip()

                val = int(a)
                rnd = -1 if b == "null" else int(b)
                arr.append((val, rnd))

            i = j
        i += 1

    return arr


def build_list(arr):
    if not arr:
        return None, []

    nodes = [Node(val) for val, _ in arr]

    for i in range(len(nodes) - 1):
        nodes[i].next = nodes[i + 1]

    for i, (_, rnd) in enumerate(arr):
        if rnd != -1:
            nodes[i].random = nodes[rnd]

    return nodes[0], nodes


def serialize(head):
    if not head:
        return "[]"

    nodes = []
    index = {}
    curr = head

    while curr:
        index[curr] = len(nodes)
        nodes.append(curr)
        curr = curr.next

    parts = []
    for node in nodes:
        if node.random is None:
            parts.append(f"[{node.val},null]")
        else:
            parts.append(f"[{node.val},{index[node.random]}]")

    return "[" + ",".join(parts) + "]"


def main():
    text = sys.stdin.read()
    arr = parse_input(text)

    if not arr:
        print("[]", end="")
        return

    head, _ = build_list(arr)
    copied = Solution().copyRandomList(head)
    print(serialize(copied), end="")


