        if (head == NULL) return NULL;

        unordered_map<Node*, Node*> mp;
        Node* curr = head;

        while (curr) {
            mp[curr] = new Node(curr->val);
            curr = curr->next;
        }

        curr = head;
        while (curr) {
            mp[curr]->next = (curr->next ? mp[curr->next] : NULL);
            mp[curr]->random = (curr->random ? mp[curr->random] : NULL);
            curr = curr->next;
        }

        return mp[head];
    }
