    char all[20000] = "";

    while (fgets(input, sizeof(input), stdin)) {
        strcat(all, input);
    }

    char tokens[2000][20];
    int n = parseTokens(all, tokens);

    struct Node* head = buildMultilevel(tokens, n);
    head = flatten(head);
    printList(head);

    return 0;
