                curr->prev = prev;
            }

            if (curr->next)
                st.push(curr->next);

            if (curr->child) {
                st.push(curr->child);
                curr->child = NULL;
            }

            prev = curr;
        }

        return head;
    }
};

string trim(const string& s) {
    int i = 0, j = (int)s.size() - 1;
    while (i <= j && isspace((unsigned char)s[i])) i++;
    while (j >= i && isspace((unsigned char)s[j])) j--;
    return (i <= j) ? s.substr(i, j - i + 1) : "";
}

vector<string> parseTokens(const string& input) {
    size_t l = input.find('[');
    size_t r = input.rfind(']');
    if (l == string::npos || r == string::npos || l > r) return {};

    string inside = input.substr(l + 1, r - l - 1);
    vector<string> tokens;
    string token;
    stringstream ss(inside);

    while (getline(ss, token, ',')) {
        tokens.push_back(trim(token));
    }

    return tokens;
}

Node* buildLevel(const vector<string>& tokens, int& idx) {
    if (idx >= (int)tokens.size() || tokens[idx] == "null")
        return NULL;

    Node* head = NULL;
    Node* tail = NULL;
    vector<Node*> nodes;

    while (idx < (int)tokens.size() && tokens[idx] != "null") {
        Node* node = new Node(stoi(tokens[idx]));
        nodes.push_back(node);

        if (!head) {
            head = tail = node;
        } else {
            tail->next = node;
            node->prev = tail;
            tail = node;
        }
        idx++;
    }

    if (idx < (int)tokens.size() && tokens[idx] == "null")
        idx++;

    for (Node* node : nodes) {
        if (idx >= (int)tokens.size())
            break;

        if (tokens[idx] == "null") {
            idx++;
        } else {
            node->child = buildLevel(tokens, idx);
        }
    }

    return head;
}

