import java.util.ArrayList;
import java.util.List;

class LRUCache {
    private final int cap;
    private final List<int[]> list; // [key, value]

    public LRUCache(int capacity) {
        this.cap = capacity;
        this.list = new ArrayList<>();
    }

    private int findKey(int key) {
        for (int i = 0; i < list.size(); i++) {
            if (list.get(i)[0] == key) return i;
        }
        return -1;
    }

    private void moveToFront(int idx) {
        if (idx <= 0 || idx >= list.size()) return;
        int[] temp = list.remove(idx);
        list.add(0, temp);
    }

    public int get(int key) {
        int idx = findKey(key);
        if (idx == -1) return -1;

        int value = list.get(idx)[1];
        moveToFront(idx);
        return value;
    }

    public void put(int key, int value) {
        if (cap <= 0) return;

        int idx = findKey(key);

        if (idx != -1) {
            list.get(idx)[1] = value;
            moveToFront(idx);
            return;
        }

        if (list.size() == cap) {
            list.remove(0);
        }

        list.add(0, new int[]{key, value});
    }
}

public class Solution {
    static int parseCapacity(String s) {
        int idx = s.indexOf("capacity");
        if (idx == -1) return 0;

        while (idx < s.length() && s.charAt(idx) != '=') idx++;
        if (idx < s.length()) idx++;

        while (idx < s.length()
                && !Character.isDigit(s.charAt(idx))
                && s.charAt(idx) != '-') {
            idx++;
        }

        StringBuilder num = new StringBuilder();
        if (idx < s.length() && s.charAt(idx) == '-') {
            num.append('-');
            idx++;
        }

        while (idx < s.length() && Character.isDigit(s.charAt(idx))) {
            num.append(s.charAt(idx));
            idx++;
        }

        return num.length() == 0 || "-".contentEquals(num) ? 0 : Integer.parseInt(num.toString());
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder inputBuilder = new StringBuilder();
        String line;

        while ((line = br.readLine()) != null) {
            if (inputBuilder.length() > 0) inputBuilder.append('\n');
            inputBuilder.append(line);
        }

        String input = inputBuilder.toString();
        int capacity = parseCapacity(input);
        LRUCache cache = new LRUCache(capacity);

        List<String> ans = new ArrayList<>();

        for (int i = 0; i < input.length(); i++) {
            if (i + 2 < input.length() && input.startsWith("put", i)) {
                int firstComma = input.indexOf(',', i);
                if (firstComma == -1) break;

                int j = firstComma + 1;
                while (j < input.length() && Character.isWhitespace(input.charAt(j))) j++;

                int start = j;
                if (j < input.length() && input.charAt(j) == '-') j++;
                while (j < input.length() && Character.isDigit(input.charAt(j))) j++;
                int key = Integer.parseInt(input.substring(start, j));

                int secondComma = input.indexOf(',', j);
                if (secondComma == -1) break;

                j = secondComma + 1;
                while (j < input.length() && Character.isWhitespace(input.charAt(j))) j++;

                start = j;
                if (j < input.length() && input.charAt(j) == '-') j++;
                while (j < input.length() && Character.isDigit(input.charAt(j))) j++;
                int value = Integer.parseInt(input.substring(start, j));

                cache.put(key, value);
                ans.add("null");
            } else if (i + 2 < input.length() && input.startsWith("get", i)) {
                int firstComma = input.indexOf(',', i);
                if (firstComma == -1) break;

                int j = firstComma + 1;
                while (j < input.length() && Character.isWhitespace(input.charAt(j))) j++;

                int start = j;
                if (j < input.length() && input.charAt(j) == '-') j++;
                while (j < input.length() && Character.isDigit(input.charAt(j))) j++;
                int key = Integer.parseInt(input.substring(start, j));

                ans.add(String.valueOf(cache.get(key)));
            }
        }

        System.out.print("[");
        for (int i = 0; i < ans.size(); i++) {
            if (i > 0) System.out.print(",");
            System.out.print(ans.get(i));
        }
        System.out.print("]");
    }
}

#include <stdio.h>
#include <string.h>
#include <ctype.h>
#include <stdlib.h>

#define MAX_ITEMS 1000
#define MAX_OUTPUT 2000
#define MAX_INPUT 10000

typedef struct {
    int key;
    int value;
} Pair;

typedef struct {
    int cap;
    Pair arr[MAX_ITEMS];
    int size;
} LRUCache;

void initCache(LRUCache* cache, int capacity) {
    cache->cap = capacity;
    cache->size = 0;
}

int findKey(LRUCache* cache, int key) {
    for (int i = 0; i < cache->size; i++) {
        if (cache->arr[i].key == key) return i;
    }
    return -1;
}

void moveToFront(LRUCache* cache, int idx) {
    if (idx <= 0 || idx >= cache->size) return;

    Pair temp = cache->arr[idx];
    for (int i = idx; i > 0; i--) {
        cache->arr[i] = cache->arr[i - 1];
    }
    cache->arr[0] = temp;
}

int get(LRUCache* cache, int key) {
    int idx = findKey(cache, key);
    if (idx == -1) return -1;

    int value = cache->arr[idx].value;
    moveToFront(cache, idx);
    return value;
}

void put(LRUCache* cache, int key, int value) {
    if (cache->cap <= 0) return;

    int idx = findKey(cache, key);

    if (idx != -1) {
        cache->arr[idx].value = value;
        moveToFront(cache, idx);
        return;
    }

    if (cache->size == cache->cap) {
        for (int i = 0; i < cache->size - 1; i++) {
            cache->arr[i] = cache->arr[i + 1];
        }
        cache->size--;
    }

    for (int i = cache->size; i > 0; i--) {
        cache->arr[i] = cache->arr[i - 1];
    }

    cache->arr[0].key = key;
    cache->arr[0].value = value;
    cache->size++;
}

int parseCapacity(const char* s) {
    const char* p = strstr(s, "capacity");
    if (p == NULL) return 0;

    while (*p && *p != '=') p++;
    if (*p == '=') p++;

    while (*p && !isdigit((unsigned char)*p) && *p != '-') p++;

    return atoi(p);
}

int main() {
    char input[MAX_INPUT] = "";
    char line[1024];

    while (fgets(line, sizeof(line), stdin)) {
        if (strlen(input) + strlen(line) < MAX_INPUT - 1) {
            strcat(input, line);
        }
    }

    int capacity = parseCapacity(input);
    LRUCache cache;
    initCache(&cache, capacity);

    char output[MAX_OUTPUT][32];
    int outCount = 0;

    for (int i = 0; input[i] != '\0'; i++) {
        if (strncmp(&input[i], "put", 3) == 0) {
            char* p1 = strchr(&input[i], ',');
            if (!p1) break;
            int key = atoi(p1 + 1);

            char* p2 = strchr(p1 + 1, ',');
            if (!p2) break;
            int value = atoi(p2 + 1);

            put(&cache, key, value);
            strcpy(output[outCount++], "null");
        }
        else if (strncmp(&input[i], "get", 3) == 0) {
            char* p1 = strchr(&input[i], ',');
            if (!p1) break;
            int key = atoi(p1 + 1);

            sprintf(output[outCount++], "%d", get(&cache, key));
        }
