class LFUCache {

    class Node {
        int key, value, freq, time;
        Node(int k, int v, int f, int t){
            key=k; value=v; freq=f; time=t;
        }
    }

    int cap;
    int timer=0;
    List<Node> list = new ArrayList<>();

    LFUCache(int capacity){
        cap = capacity;
    }

    int find(int key){
        for(int i=0;i<list.size();i++){
            if(list.get(i).key==key) return i;
        }
        return -1;
    }

    int get(int key){
        int idx = find(key);
        if(idx==-1) return -1;

        Node n = list.get(idx);
        n.freq++;
        n.time = ++timer;
        return n.value;
    }

    void put(int key,int value){
        if(cap<=0) return;

        int idx = find(key);

        if(idx!=-1){
            Node n=list.get(idx);
            n.value=value;
            n.freq++;
            n.time=++timer;
            return;
        }

        if(list.size()>=cap){
            int remove=0;

            for(int i=1;i<list.size();i++){
                Node a=list.get(i);
                Node b=list.get(remove);

                if(a.freq<b.freq || (a.freq==b.freq && a.time>b.time)){
                    remove=i;
                }
            }

            list.remove(remove);
        }

        list.add(new Node(key,value,1,++timer));
    }
}

