        if (line.equals("[]") || line.isEmpty()) {
            System.out.println("[]");
            return;
        }

        String content = line.substring(1, line.length() - 1).trim();
        if (content.isEmpty()) {
            System.out.println("[]");
            return;
        }
        String[] parts = content.split(",");
        TreeNode root = deserialize(parts);
        System.out.println(serialize(root));
    }

    public static TreeNode deserialize(String[] parts) {
        if (parts.length == 0 || parts[0].trim().equals("null")) return null;
        TreeNode root = new TreeNode(Integer.parseInt(parts[0].trim()));
        Queue<TreeNode> q = new LinkedList<>();
        q.add(root);
        int i = 1;
        while (!q.isEmpty() && i < parts.length) {
            TreeNode node = q.poll();
            if (i < parts.length && !parts[i].trim().equals("null")) {
                node.left = new TreeNode(Integer.parseInt(parts[i].trim()));
                q.add(node.left);
            }
            i++;
            if (i < parts.length && !parts[i].trim().equals("null")) {
                node.right = new TreeNode(Integer.parseInt(parts[i].trim()));
                q.add(node.right);
            }
            i++;
        }
        return root;
    }

    public static String serialize(TreeNode root) {
        if (root == null) return "[]";
        List<String> res = new ArrayList<>();
        Queue<TreeNode> q = new LinkedList<>();
        q.add(root);
        while (!q.isEmpty()) {
            TreeNode node = q.poll();
            if (node == null) {
                res.add("null");
            } else {
                res.add(String.valueOf(node.val));
                q.add(node.left);
                q.add(node.right);
            }
        }
        while (!res.isEmpty() && res.get(res.size() - 1).equals("null")) res.remove(res.size() - 1);
        return "[" + String.join(", ", res) + "]";
    }
}

import java.util.*;
public class Solution {
    static int preIdx = 0;
    static Map<Integer, Integer> map = new HashMap<>();
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (!sc.hasNextLine()) return;
        String preLine = sc.nextLine().trim();
        if (!sc.hasNextLine()) return;
        String inLine = sc.nextLine().trim();
        int[] pre = parse(preLine), in = parse(inLine);
        map.clear(); preIdx = 0;
        for (int i=0; i<in.length; i++) map.put(in[i], i);
        Node root = build(pre, 0, in.length-1);
        System.out.println(serialize(root));
    }
    static int[] parse(String s) {
        if (s.equals("[]")) return new int[0];
        String content = s.substring(1, s.length()-1).trim();
        if (content.isEmpty()) return new int[0];
        String[] p = content.split(",");
        int[] res = new int[p.length];
        for (int i=0; i<p.length; i++) res[i] = Integer.parseInt(p[i].trim());
        return res;
    }
    static class Node { int val; Node left, right; Node(int v){val=v;} }
    static Node build(int[] pre, int lo, int hi) {
        if (lo > hi || preIdx >= pre.length) return null;
        int val = pre[preIdx];
        int mid = map.get(val);
        if (mid < lo || mid > hi) return null;
        preIdx++;
        Node node = new Node(val);
        node.left = build(pre, lo, mid-1); node.right = build(pre, mid+1, hi);
        return node;
    }
    static String serialize(Node root) {
        if (root == null) return "[]";
        List<Integer> res = new ArrayList<>();
        Queue<Node> q = new LinkedList<>(); q.offer(root);
        while (!q.isEmpty()) {
            Node n = q.poll();
            if (n != null) { res.add(n.val); q.offer(n.left); q.offer(n.right); } else res.add(null);
        }
        while (!res.isEmpty() && res.get(res.size()-1) == null) res.remove(res.size()-1);
        return res.toString().replace(" ", "");
    }
}

