    char input_line[MAX_WORDS * MAX_WORD_LEN]; // Max possible input size
    if (!fgets(input_line, sizeof(input_line), stdin)) return 1;

    // Remove brackets and split by comma
    char* start = input_line;
    if (start[0] == '[') start++;
    char* end = start + strlen(start) - 1;
    while (end > start && (*end == ']' || *end == '\n' || *end == '\r')) end--;
    *(end + 1) = '\0';

    char words_str[MAX_WORDS][MAX_WORD_LEN];
    int num_words = 0;
    char* token = strtok(start, ",");
    while (token != NULL && num_words < MAX_WORDS) {
        // Remove leading/trailing spaces and quotes
        char* word_ptr = token;
        while (*word_ptr == ' ' || *word_ptr == '"') word_ptr++;
        char* word_end = word_ptr + strlen(word_ptr) - 1;
        while (word_end >= word_ptr && (*word_end == ' ' || *word_end == '"')) word_end--;
        *(word_end + 1) = '\0';
        strcpy(words_str[num_words++], word_ptr);
        token = strtok(NULL, ",");
    }

    TrieNode* root = createTrieNode();
    for (int i = 0; i < num_words; i++) {
        insert(root, words_str[i]);
    }

