#include <stdio.h>
#include <stdlib.h>
#include <string.h>

void swap(int *a, int *b) { int temp = *a; *a = *b; *b = temp; }

void heapify(int heap[], int size, int i) {
    int smallest = i;
    int l = 2 * i + 1, r = 2 * i + 2;
    if (l < size && heap[l] < heap[smallest]) smallest = l;
    if (r < size && heap[r] < heap[smallest]) smallest = r;
    if (smallest != i) { swap(&heap[i], &heap[smallest]); heapify(heap, size, smallest); }
}

int main() {
    char input[100000];
    if (!fgets(input, sizeof(input), stdin)) return 0;
    int k;
    if (scanf("%d", &k) != 1) return 0;
    int heap[k];
    int heapSize = 0;
    char *ptr = input;
    while (*ptr) {
        if (*ptr == '-' || (*ptr >= '0' && *ptr <= '9')) {
            int val = strtol(ptr, &ptr, 10);
            if (heapSize < k) {
                heap[heapSize++] = val;
                if (heapSize == k) for (int i = k / 2 - 1; i >= 0; i--) heapify(heap, k, i);
            } else if (val > heap[0]) {
                heap[0] = val;
                heapify(heap, k, 0);
            }
        } else { ptr++; }
    }
    printf("%d\n", heap[0]);
    return 0;
}

