#include <string.h>

typedef struct { int val; int freq; } Element;

void swapE(Element *a, Element *b) { Element temp = *a; *a = *b; *b = temp; }

void minHeapify(Element heap[], int size, int i) {
    int smallest = i;
    int left = 2 * i + 1, right = 2 * i + 2;
    if (left < size && heap[left].freq < heap[smallest].freq) smallest = left;
    if (right < size && heap[right].freq < heap[smallest].freq) smallest = right;
    if (smallest != i) { swapE(&heap[i], &heap[smallest]); minHeapify(heap, size, smallest); }
}

int cmpInt(const void* a, const void* b) { return *(int*)a - *(int*)b; }

