        else ptr++;
    }
    Element freq[5000];
    for (int i = 0; i < count; i++) {
        int found = 0;
        for (int j = 0; j < distinct; j++) {
            if (freq[j].val == nums[i]) { freq[j].freq++; found = 1; break; }
        }
        if (!found) { freq[distinct].val = nums[i]; freq[distinct++].freq = 1; }
    }
    if (k > distinct) k = distinct;
    Element heap[k];
    for (int i = 0; i < k; i++) heap[i] = freq[i];
    for (int i = k / 2 - 1; i >= 0; i--) minHeapify(heap, k, i);
    for (int i = k; i < distinct; i++) {
        if (freq[i].freq > heap[0].freq) {
            heap[0] = freq[i];
            minHeapify(heap, k, 0);
        }
    }
    int res[k];
    for (int i = 0; i < k; i++) res[i] = heap[i].val;
