    while (n > 1) {
        int y = st[0]; st[0] = st[--n]; heapify(st, n, 0);
        int x = st[0]; st[0] = st[--n]; heapify(st, n, 0);
        if (y != x) {
            st[n++] = y - x;
            // Bubble up
            int i = n - 1;
            while (i > 0 && st[(i-1)/2] < st[i]) {
                swap(&st[i], &st[(i-1)/2]);
                i = (i-1)/2;
            }
        }
    }
