int lo, maxLen;

void expandAroundCenter(char* s, int j, int k, int len) {
    while (j >= 0 && k < len && s[j] == s[k]) {
        j--;
        k++;
    }
    if (maxLen < k - j - 1) {
        lo = j + 1;
        maxLen = k - j - 1;
    }
}

