    if (s_len > 0 && s_input[s_len - 1] == '\r') s_input[--s_len] = '\0';

    char* s_ptr = s_input;
    if (s_len >= 2 && s_input[0] == '"' && s_input[s_len - 1] == '"') {
        s_ptr++;
        s_input[s_len - 1] = '\0';
        s_len -= 2;
    }

    if (s_len == 0) {
        printf("\"\"\n");
        return 0;
    }

    lo = 0;
    maxLen = 0;

    for (int i = 0; i < s_len; i++) {
        expandAroundCenter(s_ptr, i, i, s_len);
        expandAroundCenter(s_ptr, i, i + 1, s_len);
    }

    printf("\"");
    for (int i = 0; i < maxLen; i++) {
        putchar(s_ptr[lo + i]);
    }
    printf("\"\n");

    return 0;
}

